// Component/prop names follow the standard Jinx UI surface — verify against your installed @jinx-ui/react version.
import { useId, useState } from 'react';
import {
  Badge,
  Card,
  Divider,
  Field,
  Heading,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type Theme = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const THEME_OPTIONS: ReadonlyArray<{ value: Theme; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: ReadonlyArray<{ value: FontFamily; label: string }> = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const scaleId = useId();
  const fontId = useId();

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <Card
      as="section"
      aria-label="Настройки внешнего вида"
      style={{ maxWidth: 'var(--jx-size-container-sm)', padding: 'var(--jx-space-6)' }}
    >
      <Stack direction="column" gap="var(--jx-space-6)">
        <Stack direction="row" align="center" justify="space-between" gap="var(--jx-space-3)">
          <Heading level={2}>Внешний вид</Heading>
          <Badge variant="subtle">{themeLabel}</Badge>
        </Stack>

        <Field label="Тема оформления">
          <SegmentedControl
            value={settings.theme}
            options={THEME_OPTIONS}
            onChange={(theme: Theme) => update({ theme })}
            aria-label="Тема оформления"
            fullWidth
          />
        </Field>

        <Field
          label="Масштаб интерфейса"
          htmlFor={scaleId}
          hint="Влияет на размер текста и отступов"
        >
          <Stack direction="row" align="center" gap="var(--jx-space-4)">
            <Slider
              id={scaleId}
              min={80}
              max={140}
              step={5}
              value={settings.scale}
              onChange={(scale: number) => update({ scale })}
              style={{ flex: 1 }}
            />
            <Text
              variant="mono"
              style={{ minWidth: 'var(--jx-space-12)', textAlign: 'right' }}
            >
              {settings.scale}%
            </Text>
          </Stack>
        </Field>

        <Switch
          checked={settings.dense}
          onChange={(dense: boolean) => update({ dense })}
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами"
        />

        <Divider />

        <Stack direction="column" gap="var(--jx-space-4)">
          <Heading level={3}>Ещё</Heading>
          <Field label="Шрифт" htmlFor={fontId}>
            <Select
              id={fontId}
              value={settings.font}
              options={FONT_OPTIONS}
              onChange={(font: FontFamily) => update({ font })}
            />
          </Field>
        </Stack>
      </Stack>
    </Card>
  );
}

